Edit 6: energyBudget query:

```java
@Transactional(readOnly = true)
public EnergyBudgetResponse energyBudget(String channelId, LocalDate businessDay) {
    repo.findChannel(channelId).orElseThrow(404);
    Optional<PublicationRow> publication = repo.findLatestPublication(channelId, businessDay);
    if (publication.isEmpty()) {
        return new EnergyBudgetResponse(channelId, businessDay.toString(), null, null,
                ENERGY_WINDOW_SECONDS, ENERGY_BUDGET_LIMIT, null, ENERGY_BUDGET_NOTE);
    }
    List<PublicationSegmentRow> segments = repo.findPublicationSegments(publication.get().id());
    List<EnergySegment> energySegments = segments.stream().map(s -> new EnergySegment(
            s.segmentId(), s.assetId(), s.energyDensityMilli(), s.startMs(), s.endMs())).toList();
    WindowEvaluation max = evaluateMaxWindow(energySegments);
    EnergyWindowEvidence evidence = max == null ? null : new EnergyWindowEvidence(
            atMs(max.startMs()), atMs(max.endMs()), energyOf(max.energyMicro()),
            max.contributions().stream().map(c -> new SegmentEnergyContribution(
                    c.segmentId(), c.assetId(), densityOf(c.densityMilli()), c.overlapMs(),
                    energyOf(c.energyMicro()))).toList());
    return new EnergyBudgetResponse(channelId, businessDay.toString(), publication.get().id(),
            publication.get().publishedVersion(), ENERGY_WINDOW_SECONDS, ENERGY_BUDGET_LIMIT,
            evidence, ENERGY_BUDGET_NOTE);
}
```

